import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { App } from './App'
// Fonts before tokens: `tokens.css` names the families in `--font-ui` / `--font-mono`, and
// a face that is not yet declared when the first frame paints shows the fallback stack for
// a beat. Both are bundled locally — the CSP names no external font host.
import './styles/fonts.css'
import './styles/tokens.css'
/*
 * Generated by `vendor-ui-icons.mjs`: the handful of marks CSS has to draw itself, because their
 * site is a `content:` rule rather than a component — the lint gutter and the markdown preview's
 * external-link marker. After `tokens.css`, since the rules that use them read `--icon-*` for
 * their box size.
 */
import './styles/iconMasks.css'
/*
 * The colours for `editor/highlight.ts`'s token classes. (M20)
 *
 * Here, and not beside the code that emits them, for a reason worth writing down: `highlight.ts`
 * is compiled and *run under node* by `check:editor`, where a `.css` import cannot resolve. So
 * the stylesheet is loaded by the app entry instead — which is also where it belongs, since these
 * are global class names (CodeMirror writes the literal `cide-tk-keyword` onto its spans, so they
 * cannot be hashed) painting a concern shared by every surface that highlights code.
 *
 * They used to live inside `EditorSurface.module.css`, scoped under that module's `.body`. That
 * made them apply inside an `EditorSurface` and nowhere else, which was invisible until the merge
 * resolver started highlighting too and got plain text with nothing failing.
 */
import './editor/highlight.css'
import { installConsoleBridge } from './ipc/consoleBridge'
import { installThemeSync } from './settings/useSettings'

const root = document.getElementById('root')
if (!root) throw new Error('#root is missing from index.html')

// First of the two, so anything the rest of the boot throws is written down rather than lost
// in a console nothing can read. A no-op unless `CIDE_CONSOLE_BRIDGE=1` asked for it.
installConsoleBridge()

// Make this window follow a theme change made in a *different* window.
//
// `applyTheme` moves the local field and persists; every other window learns about it only
// through `cide://workspace-changed`, and that event replaces `boot` — which is not the field
// driving `documentElement.dataset.theme`. Without this subscription a second window keeps its
// old palette until it is restarted, and its terminals keep their old resolved colour tables,
// which is exactly what was reported.
//
// Two jobs, and the order matters. It first settles what theme this window *starts* on, taken
// from the `<html data-theme>` that `theme-boot.js` wrote in `<head>`, and only then subscribes
// — so the store's pre-hydration seed never gets painted over the resolved value.
//
// Here rather than in an `App` effect for two reasons. It is window-lifetime, not component
// lifetime: module scope runs once per webview, so StrictMode's double-mount cannot install it
// twice and no unmount can tear it down while the window is still open. And it must run before
// the first render, because a `TerminalPane` mounted in that render builds an xterm that reads
// the tokens at construction — an effect would hand it the wrong palette and then correct it.
installThemeSync()

// StrictMode double-invokes effects in development, which is exactly the pressure a pane
// host registry should be under: spawning a PTY twice per pane would be a real bug, and
// `TerminalPane`'s per-pane spawn guard is what prevents it. Leaving StrictMode on keeps
// that guard honest.
createRoot(root).render(
  <StrictMode>
    <App />
  </StrictMode>,
)
